package org.eclipse.rdf4j.sail.lmdb.evaluation;

import java.util.concurrent.atomic.AtomicInteger;

/**
 * Per-query probe cap: a large query performs many dispatch decisions, and without this bound each could independently
 * afford a probe from accumulated store credit — the "it gets slower every operator" experience the spacing rule alone
 * cannot prevent within one query. Carried on the query's row state and inherited by child scopes.
 */
final class LmdbNativeQueryProbeBudget {

	private final AtomicInteger probes = new AtomicInteger();

	boolean tryConsume(int maxPerQuery) {
		while (true) {
			int current = probes.get();
			if (current >= maxPerQuery) {
				return false;
			}
			if (probes.compareAndSet(current, current + 1)) {
				return true;
			}
		}
	}

	/** Returns a consumed slot (the probe was declined before it started). */
	void release() {
		probes.updateAndGet(current -> Math.max(0, current - 1));
	}

	int consumed() {
		return probes.get();
	}
}
